export enum UserRole {
  ADMIN = 'admin',
  SUBMITTER = 'submitter',
  APPROVER = 'approver',
  DATA_ENTRY = 'data_entry',
  DATA_APPROVER = 'data_approver',
  VERIFIER = 'verifier'
}

export enum BillStatus {
  DRAFT = 'draft',
  SUBMITTED = 'submitted',
  APPROVED = 'approved',
  REJECTED = 'rejected',
  DATA_ENTRY_PENDING = 'data_entry_pending',
  DATA_ENTRY_COMPLETED = 'data_entry_completed',
  DATA_APPROVED = 'data_approved',
  DATA_REJECTED = 'data_rejected',
  VERIFIED = 'verified',
  FINAL_APPROVED = 'final_approved',
  FINAL_REJECTED = 'final_rejected'
}

export interface User {
  id: string;
  username: string;
  email: string;
  roles: UserRole[];
  createdAt: Date;
  createdBy: string;
}

export interface Bill {
  id: string;
  title: string;
  description: string;
  amount: number;
  fileName: string;
  fileUrl: string;
  status: BillStatus;
  submittedBy: string;
  submittedAt: Date;
  auditTrail: AuditEntry[];
  dataEntry?: BillDataEntry;
}

export interface BillDataEntry {
  id: string;
  billId: string;
  vendor: string;
  invoiceNumber: string;
  invoiceDate: Date;
  dueDate: Date;
  category: string;
  lineItems: LineItem[];
  enteredBy: string;
  enteredAt: Date;
}

export interface LineItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface AuditEntry {
  id: string;
  action: string;
  performedBy: string;
  performedAt: Date;
  details: string;
  previousStatus?: BillStatus;
  newStatus?: BillStatus;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
}

export interface AppState {
  users: User[];
  bills: Bill[];
  currentUser: User | null;
}